use super::*;

/// 🔺️ One actual triangle index row is atomic, fully priced, and never grows its admitted original buffers.
#[test]
fn original_mesh_tessellation_triangle_emission_prices_exact_atomic_output(){
    use crate::brep::queries::tessellation::tests::observe_tessellation_system as observe;
    use protocol::value::{retained_clone::{RetainedCloneGrant,RetainedCloneProgress},retirement::controlled::ControlledRetirement};
    let law:serde_json::Value=serde_json::from_str(include_str!("../../../🧫️fixtures/🧩️tessellation/🎟️owners.json")).unwrap();let indices:[u32;3]=serde_json::from_value(law["triangleEmission"]["indices"].clone()).unwrap();
    for close_copy in law["copyGrants"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as usize){
        let(mut job,source)=observe(||{let mut job=MeshTessellationJob::new(super::tessellation_metadata_tests::authored_source(&law));while !job.buffer_reservation_complete(){let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:job.next_buffer_capacity_byte_demand(0).unwrap(),maximum_release_bytes:0,maximum_depth:job.next_buffer_depth_demand().unwrap()};job.reserve_buffer_step(grant).unwrap();}while !job.metadata_capture_complete(){let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:job.next_metadata_depth_demand().unwrap()};job.capture_metadata_step(grant).unwrap();}while job.phase!=7{job.advance().unwrap();}for local in 0..3{let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:job.next_corner_copy_byte_demand(local).unwrap(),maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:job.next_corner_depth_demand(local).unwrap()};job.emit_corner_step(local,grant).unwrap();}job});
        let original=job.mesh.vertices.as_ptr();let out=job.output.as_ref().unwrap();let pointers=(out.indices.as_ptr(),out.face_ids.as_ptr());let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:job.next_triangle_copy_byte_demand(indices).unwrap(),maximum_capacity_bytes:job.next_triangle_capacity_byte_demand(indices,16).unwrap(),maximum_release_bytes:job.next_triangle_release_byte_demand(indices).unwrap(),maximum_depth:job.next_triangle_depth_demand(indices).unwrap()};assert_eq!(grant.maximum_copy_bytes,law["triangleEmission"]["copyBytes"].as_u64().unwrap()as usize);
        for denied in[RetainedCloneGrant {maximum_items:0,..grant},RetainedCloneGrant {maximum_copy_bytes:0,..grant},RetainedCloneGrant {maximum_copy_bytes:1,..grant},RetainedCloneGrant {maximum_copy_bytes:3,..grant},RetainedCloneGrant {maximum_copy_bytes:grant.maximum_copy_bytes-1,..grant},RetainedCloneGrant {maximum_depth:grant.maximum_depth-1,..grant}]{let(step,heap)=observe(||job.emit_triangle_step(indices,denied).unwrap());assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!(job.triangle_receipt.0,RetainedCloneProgress::default());assert_eq!(heap,(0,0));let out=job.output.as_ref().unwrap();assert!(out.indices.is_empty()&&out.face_ids.is_empty());assert_eq!((out.indices.as_ptr(),out.face_ids.as_ptr()),pointers);assert_eq!(job.mesh.vertices.as_ptr(),original);}
        let(step,heap)=observe(||job.emit_triangle_step(indices,grant).unwrap());assert_eq!(heap,(0,0));assert!(step.progress().fits(grant));assert_eq!(step.progress().copied_items,1);assert_eq!(step.progress().copied_bytes,grant.maximum_copy_bytes);let out=job.output.as_ref().unwrap();assert_eq!(out.indices,indices);assert_eq!(out.face_ids,[law["triangleEmission"]["faceId"].as_u64().unwrap()as u32]);assert_eq!((out.indices.as_ptr(),out.face_ids.as_ptr()),pointers);assert_eq!(job.mesh.vertices.as_ptr(),original);
        let(mut owner,handoff)=observe(||ControlledRetirement::new(job).unwrap_or_else(|_|panic!("original triangle closure unsupported")));assert_eq!(handoff,(0,0));let(mut born,mut freed,mut turns)=(source.0,source.1,0);while !owner.terminal_is_empty(){let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:close_copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(close_copy).unwrap(),maximum_release_bytes:owner.next_release_byte_demand().unwrap(),maximum_depth:owner.next_depth_demand().unwrap()};let(step,heap)=observe(||owner.step(grant).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(step.progress().fits(grant));born+=heap.0;freed+=heap.1;turns+=1;assert!(turns<100000);}
        assert_eq!(born,freed);let(_,heap)=observe(||drop(owner));assert_eq!(heap,(0,0));eprintln!("[DEBUG] Original Mesh atomic triangle copied=16 underAtomic1and3Refused=true sameSource=true sameBacking=true physical={freed} closeCopy={close_copy} terminalDrop=0");
    }
}
